import re


_DURATION_RE = re.compile(
    r"(?:([0-9]+)d)?(?:([0-9]+)h)?(?:([0-9]+)m)?(?:([0-9]+)s)?"
)


def parse_duration(s):
    """Parse a duration string such as '1h30m' into an integer number of seconds."""
    if not isinstance(s, str):
        raise ValueError("duration must be a string")

    text = s.strip()
    if not text:
        raise ValueError("invalid duration")

    match = _DURATION_RE.fullmatch(text)
    if match is None:
        raise ValueError("invalid duration: {!r}".format(s))

    days, hours, minutes, seconds = (
        int(value) if value is not None else 0 for value in match.groups()
    )
    return days * 86400 + hours * 3600 + minutes * 60 + seconds
